
    
const APP_VERSION = 'wobench-v29.24';
function fmtMoney(n) {
  var v = Number(n);
  if (!isFinite(v)) v = 0;
  v = Math.round(v * 100) / 100;
  return v.toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

