    document.querySelectorAll('[data-icon]').forEach(function (el) {
      var k = el.getAttribute('data-icon');
      el.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">' + (ICONS[k] || '') + '</svg>';
    });

    const modules = document.querySelectorAll('.module');
    const bottomItems = document.querySelectorAll('.bottom-item');
    const mineEntries = document.querySelectorAll('.mine-entry');
    const BOTTOM_TABS = ['homepage', 'shiti', 'study', 'xiushen', 'mine'];
    let navStack = [];

    function showModule(target, opts) {
      opts = opts || {};
      modules.forEach(m => {
        m.classList.toggle('hidden', m.id !== target);
      });
      // 设置页面单项显示逻辑
      if (target === 'settings' && opts.settingsTarget) {
        var allSettingsCards = document.querySelectorAll('#settings > .card');
        var targetCard = document.getElementById(opts.settingsTarget);
        allSettingsCards.forEach(function(c) {
          c.style.display = (c === targetCard) ? '' : 'none';
        });
        // 更新标题为对应项名称
        var titleEl = document.querySelector('#settings .module-title');
        if (titleEl && targetCard) {
          var cardTitle = targetCard.querySelector('.card-title');
          if (cardTitle) titleEl.textContent = cardTitle.textContent.replace(/\s*[\d\s]*$/, '').trim();
        }
        var subEl = document.querySelector('#settings .module-subtitle');
        if (subEl) subEl.style.display = 'none';
        // 「我的」头像/名称/签名固定显示在该项内容上方
        populateSettingsMineHead();
        var mh = document.getElementById('settingsMineHead');
        if (mh) mh.style.display = '';
        if (titleEl) titleEl.style.display = 'none';
      } else if (target === 'settings') {
        // 无 target 时显示全部设置卡片
        var allCards = document.querySelectorAll('#settings > .card');
        allCards.forEach(function(c) { c.style.display = ''; });
        var tEl = document.querySelector('#settings .module-title');
        if (tEl) { tEl.textContent = '设置'; tEl.style.display = ''; }
        var sEl = document.querySelector('#settings .module-subtitle');
        if (sEl) sEl.style.display = '';
        var mh2 = document.getElementById('settingsMineHead');
        if (mh2) mh2.style.display = 'none';
      }
      updateModuleHeaderDate(target);
      switchModuleTab(target, 'today');
      if (target === 'home') { renderCal(); renderDetail(todayStr); renderHomeSummary(); renderReview('week'); renderStreakBadges(); }
      else if (target === 'homepage') { renderHomepage(); renderReport('month'); renderTrend(7); }
      else if (target === 'lingguang') renderInspirationList();
      else if (target === 'zichan') { renderTransactions(); renderTodayTx(); renderAssetSummary(); }
      else if (DAILY_MODS.indexOf(target) >= 0) {
        const rec = store[ymd(new Date()) + '|' + target];
        if (rec) { const el = document.getElementById(target); if (el) fillForm(el, rec.fields); }
        renderHistory(target);
        if (target === 'xiushen') { renderXiushenDaily(todayStr); renderYanghuList(); renderYanghuHistory(); }
        if (target === 'study') { renderStudyPeriod(); renderTcm(); renderStudyTimeCard(); renderTcmHistory(); renderReadingList(); }
      }
      else if (target === 'todo') { renderTodo(); renderTodoTagRow(); }
      else if (target === 'favorite') { renderFavGrid(); renderReadingList(); }
      else if (target === 'mine') renderMine();
      if (BOTTOM_TABS.indexOf(target) >= 0) {
        bottomItems.forEach(n => n.classList.toggle('active', n.dataset.module === target));
      }
    }

    function setBackUI() {
      const hasBack = navStack.length > 1;
      const pf = document.querySelector('.phone-frame');
      if (pf) pf.classList.toggle('has-back', hasBack);
      const bb = document.getElementById('backBtn');
      if (bb) bb.classList.toggle('hidden', !hasBack);
    }

    // mode: 'reset' 根级切换(清空栈) | 'push' 入栈(来自我的/快捷) | 'keep' 不改变栈(返回)
    function switchTo(target, opts) {
      opts = opts || {};
      // 切走当前模块前，先把未落盘的今日面板保存，避免填了的「身体变化」等数据在切换时丢失
      const curMod = document.querySelector('.module:not(.hidden)');
      if (curMod && AUTOSAVE_MODS.indexOf(curMod.id) >= 0) flushAutoSave(curMod.id);
      if (opts.reset || (BOTTOM_TABS.indexOf(target) >= 0 && !opts.keep)) {
        navStack = [target];
      } else if (opts.push) {
        if (navStack.length === 0) navStack = [target];
        else if (navStack[navStack.length - 1] !== target) navStack.push(target);
      }
      showModule(target, opts);
      setBackUI();
    }

    function goBack() {
      if (navStack.length <= 1) return;
      navStack.pop();
      const prev = navStack[navStack.length - 1];
      switchTo(prev, { keep: true });
    }

    bottomItems.forEach(item => {
      item.addEventListener('click', () => {
        switchTo(item.dataset.module, { reset: true });
      });
    });

    mineEntries.forEach(entry => {
      entry.addEventListener('click', () => {
        if (navStack.length === 0) navStack = ['mine'];
        var targetSettings = entry.dataset.settings || '';
        switchTo(entry.dataset.module, { push: true, settingsTarget: targetSettings });
      });
    });

    document.querySelectorAll('.quick-icon').forEach(function (qi) {
      qi.addEventListener('click', function () {
        switchTo(qi.getAttribute('data-qi'), { push: true });
      });
    });

    const backBtnEl = document.getElementById('backBtn');
    if (backBtnEl) backBtnEl.addEventListener('click', goBack);

    // 通用单选（标签 / 选项）
    document.querySelectorAll('.choice-row').forEach(row => {
      row.addEventListener('click', e => {
        const choice = e.target.closest('.choice');
        if (!choice) return;
        row.querySelectorAll('.choice').forEach(c => c.classList.remove('active'));
        choice.classList.add('active');
      });
    });

    // 灵光闪现标签多选
    document.querySelectorAll('.tag-group').forEach(group => {
      group.addEventListener('click', e => {
        const tag = e.target.closest('.tag');
        if (tag) tag.classList.toggle('active');
      });
    });

    // 天气 / 心情 图标选择
    document.querySelectorAll('.pick-grid').forEach(grid => {
      grid.addEventListener('click', e => {
        const item = e.target.closest('.pick-item');
        if (!item) return;
        grid.querySelectorAll('.pick-item').forEach(i => i.classList.remove('active'));
        item.classList.add('active');
      });
    });

    // ============ 农历（动态计算，数据表 1900-2099，已与 cnlunar 校验） ============
    var LUNAR_INFO = [0x4bd8,0x4ae0,0xa570,0x54d5,0xd260,0xd950,0x16554,0x56a0,0x9ad0,0x55d2,0x4ae0,0xa5b6,0xa4d0,0xd250,0x1d255,0xb540,0xd6a0,0xada2,0x95b0,0x14977,0x4970,0xa4b0,0xb4b5,0x6a50,0x6d40,0x1ab54,0x2b60,0x9570,0x52f2,0x4970,0x6566,0xd4a0,0xea50,0x6e95,0x5ad0,0x2b60,0x186e3,0x92e0,0x1c8d7,0xc950,0xd4a0,0x1d8a6,0xb550,0x56a0,0x1a5b4,0x25d0,0x92d0,0xd2b2,0xa950,0xb557,0x6ca0,0xb550,0x15355,0x4da0,0xa5b0,0x14573,0x52b0,0xa9a8,0xe950,0x6aa0,0xaea6,0xab50,0x4b60,0xaae4,0xa570,0x5260,0xf263,0xd950,0x5b57,0x56a0,0x96d0,0x4dd5,0x4ad0,0xa4d0,0xd4d4,0xd250,0xd558,0xb540,0xb6a0,0x195a6,0x95b0,0x49b0,0xa974,0xa4b0,0xb27a,0x6a50,0x6d40,0xaf46,0xab60,0x9570,0x4af5,0x4970,0x64b0,0x74a3,0xea50,0x6b58,0x55c0,0xab60,0x96d5,0x92e0,0xc960,0xd954,0xd4a0,0xda50,0x7552,0x56a0,0xabb7,0x25d0,0x92d0,0xcab5,0xa950,0xb4a0,0xbaa4,0xad50,0x55d9,0x4ba0,0xa5b0,0x15176,0x52b0,0xa930,0x7954,0x6aa0,0xad50,0x5b52,0x4b60,0xa6e6,0xa4e0,0xd260,0xea65,0xd530,0x5aa0,0x76a3,0x96d0,0x4afb,0x4ad0,0xa4d0,0x1d0b6,0xd250,0xd520,0xdd45,0xb5a0,0x56d0,0x55b2,0x49b0,0xa577,0xa4b0,0xaa50,0x1b255,0x6d20,0xada0,0x14b63,0x9370,0x49f8,0x4970,0x64b0,0x168a6,0xea50,0x6b20,0x1a6c4,0xaae0,0xa2e0,0xd2e3,0xc960,0xd557,0xd4a0,0xda50,0x5d55,0x56a0,0xa6d0,0x55d4,0x52d0,0xa9b8,0xa950,0xb4a0,0xb6a6,0xad50,0x55a0,0xaba4,0xa5b0,0x52b0,0xb273,0x6930,0x7337,0x6aa0,0xad50,0x14b55,0x4b60,0xa570,0x54e4,0xd160,0xe968,0xd520,0xdaa0,0x16aa6,0x56d0,0x4ae0,0xa9d4,0xa2d0,0xd150,0xf252,0xd520];
    var GAN = ['甲','乙','丙','丁','戊','己','庚','辛','壬','癸'];
    var ZHI = ['子','丑','寅','卯','辰','巳','午','未','申','酉','戌','亥'];
    var L_MONTHS = ['正','二','三','四','五','六','七','八','九','十','冬','腊'];
    var L_DAY2 = ['日','一','二','三','四','五','六','七','八','九','十'];
    function lLeapMonth(y){ return LUNAR_INFO[y-1900] & 0xf; }
    function lLeapDays(y){ if(lLeapMonth(y)) return (LUNAR_INFO[y-1900] & 0x10000) ? 30 : 29; return 0; }
    function lMonthDays(y,m){ return (LUNAR_INFO[y-1900] & (0x10000 >> m)) ? 30 : 29; }
    function lYearDays(y){ var s=348,i=0x8000; while(i>0x8){ if(LUNAR_INFO[y-1900]&i) s++; i>>=1; } return s+lLeapDays(y); }
    function lunarCn(dateStr){
      var p = String(dateStr).split('-');
      var y = parseInt(p[0],10), m = parseInt(p[1],10), d = parseInt(p[2],10);
      var off = Math.round((Date.UTC(y,m-1,d) - Date.UTC(1900,0,31))/86400000);
      var i=1900;
      while(i<2101 && off>0){ off-=lYearDays(i); i++; }
      if(off<0){ off+=lYearDays(i-1); i--; }
      var ly=i, leap=lLeapMonth(ly), isLeap=false, lm=1, temp=0;
      while(lm<13 && off>0){
        if(leap>0 && lm==(leap+1) && !isLeap){ lm--; isLeap=true; temp=lLeapDays(ly); }
        else { temp=lMonthDays(ly,lm); }
        if(isLeap && lm==(leap+1)) isLeap=false;
        off-=temp; lm++;
      }
      if(off==0 && leap>0 && lm==leap+1){ if(isLeap){ isLeap=false; } else { isLeap=true; lm--; } }
      if(off<0){ off+=temp; lm--; }
      var ld=off+1;
      var gy=(ly-1984)%10, gz=(ly-1984)%12; gy=(gy+10)%10; gz=(gz+12)%12;
      var ys=GAN[gy]+ZHI[gz];
      var ms = isLeap ? ('闰'+L_MONTHS[leap-1]+'月') : (L_MONTHS[lm-1]+'月');
      var dstr;
      if(ld<=10) dstr='初'+L_DAY2[ld];
      else if(ld<20) dstr='十'+L_DAY2[ld-10];
      else if(ld==20) dstr='二十';
      else if(ld<30) dstr='廿'+L_DAY2[ld-20];
      else dstr='三十';
      return ys+'年'+ms+dstr;
    }
    function ymd(d) {
      return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
    }
    function weekCn(d) {
      return '周' + '日一二三四五六'[d.getDay()];
    }
    const todayStr = ymd(new Date());

    // ============ 修身养性 · 每日内容（按日期循环）============
    const JINGWEN = {
      daodejing: [
        { title: '第一章', chapter: '第一章', source: '《道德经》', text: '道可道，非常道；名可名，非常名。无名，天地之始；有名，万物之母。故常无欲，以观其妙；常有欲，以观其徼。此两者同出而异名，同谓之玄。玄之又玄，众妙之门。', explain: '能用言语说出的道，已不是那永恒不变的道；能定下的名，也不是那恒定的名。无，是天地的本始；有，是万物的根源。放下执念，才能体察道的微妙；带着分别，只能看见表象的边界。二者同源而异名，皆称之为玄——玄之又玄，便是万有生发的门户。读经不在记诵，而在以静心去印证那不可言说之境。' },
        { title: '第二章', chapter: '第二章', source: '《道德经》', text: '天下皆知美之为美，斯恶已；皆知善之为善，斯不善已。故有无相生，难易相成，长短相形，高下相倾，音声相和，前后相随。是以圣人处无为之事，行不言之教；万物作焉而不辞，生而不有，为而不恃，功成而弗居。夫唯弗居，是以不去。', explain: '美丑、善恶、有无、难易，皆是相对而生、彼此成就的概念。一旦执着于标准，对立便生。圣人顺任自然、不妄加干预，让万物自生自长，既不占有也不居功。正因为不把功劳挂在自己身上，那功反而在众生心中长存。放下对结果的抓取，恰恰是成就的秘诀。' },
        { title: '第三章', chapter: '第三章', source: '《道德经》', text: '不尚贤，使民不争；不贵难得之货，使民不为盗；不见可欲，使民心不乱。是以圣人之治，虚其心，实其腹，弱其志，强其骨。常使民无知无欲，使夫智者不敢为也。为无为，则无不治。', explain: '不刻意标榜贤能，百姓便不争名；不炒作稀缺之物，便无人起盗心。治理之道在于让心虚静、身体安饱、意志柔和而筋骨强健。少一些人为的煽动与诱惑，人心自然清明。无为而治，不是什么都不做，而是不妄为、不扰民，事事自得其序。' },
        { title: '第四章', chapter: '第四章', source: '《道德经》', text: '道冲，而用之或不盈。渊兮，似万物之宗；湛兮，似或存。吾不知谁之子，象帝之先。', explain: '道看似空虚无物，作用起来却永不枯竭。它深不可测，像是万物的本源；它隐微难见，却又真实存在。我不知它由谁所生，似乎在一切天帝之前便已存在。这正是道的奇妙——空，却包纳万有；无形，却是万物之根。' },
        { title: '第五章', chapter: '第五章', source: '《道德经》', text: '天地不仁，以万物为刍狗；圣人不仁，以百姓为刍狗。天地之间，其犹橐籥乎？虚而不屈，动而愈出。多言数穷，不如守中。', explain: '天地无私，对万物一视同仁，任其生灭，不偏不倚；圣人效法天地，对百姓也无亲疏分别。天地之间如同风箱，空虚却不匮乏，越鼓动越生生不息。人若多言多事，往往很快陷入困穷；不如守持中道，虚静而容。少说多做，留白自有生机。' },
        { title: '第六章', chapter: '第六章', source: '《道德经》', text: '谷神不死，是谓玄牝。玄牝之门，是谓天地根。绵绵若存，用之不勤。', explain: '虚空而灵妙的道永不停息，称作玄妙的母性。那生育之门，便是天地的根本。它绵绵密密、似有似无，作用却永不倦怠。修行者若能体会这虚中藏有的生机，便知生命之源不在外求，而在那看似空无的深处源源不绝。' },
        { title: '第七章', chapter: '第七章', source: '《道德经》', text: '天长地久。天地所以能长且久者，以其不自生，故能长生。是以圣人后其身而身先，外其身而身存。非以其无私邪？故能成其私。', explain: '天地长久，正因它们不为自己而活，反而能永存。圣人把自身退后，众人却推他向前；把自身置之度外，反而得以保全。这难道不是无私的回报吗？越是放下对小我的计较，越能在更广阔的维度上成就自己。利他，终利己。' },
        { title: '第八章', chapter: '第八章', source: '《道德经》', text: '上善若水。水善利万物而不争，处众人之所恶，故几于道。居善地，心善渊，与善仁，言善信，政善治，事善能，动善时。夫唯不争，故无尤。', explain: '最高的善如同水：滋养万物而不争抢，甘居众人所恶的低处，所以最接近道。处世要像水那样——安于下位、心如深潭、待人仁爱、出言守信、为政清平、做事胜任、行动应时。正因不与万物相争，才终无过失。柔处下位，是大智慧。' },
        { title: '第九章', chapter: '第九章', source: '《道德经》', text: '持而盈之，不如其已；揣而锐之，不可长保。金玉满堂，莫之能守；富贵而骄，自遗其咎。功成身退，天之道也。', explain: '执意要把杯子斟满，不如适时停下；把锋芒磨得锐利，难以长久保全。金玉堆满厅堂，无人能永远守住；因富贵而骄横，反给自己招祸。功业成就便懂得退身，才是合乎天道的活法。知足知止，才能善始善终。' },
        { title: '第十章', chapter: '第十章', source: '《道德经》', text: '载营魄抱一，能无离乎？专气致柔，能如婴儿乎？涤除玄鉴，能无疵乎？爱民治国，能无为乎？天门开阖，能为雌乎？明白四达，能无知乎？', explain: '身体与精神能否合一不离散？聚敛精气能否柔顺如初生婴儿？涤净内心明镜能否纤尘不染？爱民治国能否无为而治？感官开合能否安守柔静？通达四方能否不逞机心？这一连串反问，正是修身的总纲——返璞归真，身心合一。' },
        { title: '第十一章', chapter: '第十一章', source: '《道德经》', text: '三十辐共一毂，当其无，有车之用。埏埴以为器，当其无，有器之用。凿户牖以为室，当其无，有室之用。故有之以为利，无之以为用。', explain: '三十根辐条凑于车毂，正因中间的空虚，车轮才能转动；揉泥制器，正因内部的空，才能盛物；开门窗造屋，正因屋内的空，才能居住。所以实有之物给人便利，而那虚空之处才真正发挥作用。留白与余地，比填满更有力量。' },
        { title: '第十二章', chapter: '第十二章', source: '《道德经》', text: '五色令人目盲；五音令人耳聋；五味令人口爽；驰骋畋猎，令人心发狂；难得之货，令人行妨。是以圣人为腹不为目，故去彼取此。', explain: '过度追逐声色五味与田猎珍宝，只会让感官麻木、心神狂乱、行为失当。圣人但求腹饱心安，不为耳目之欲所役。这一章是对现代人的精准预言——信息过载、刺激过量的时代，少则得，减则明，回归朴素方能守住清明。' },
        { title: '第十三章', chapter: '第十三章', source: '《道德经》', text: '宠辱若惊，贵大患若身。何谓宠辱若惊？宠为下，得之若惊，失之若惊，是谓宠辱若惊。何谓贵大患若身？吾所以有大患者，为吾有身，及吾无身，吾有何患？故贵以身为天下，若可寄天下；爱以身为天下，若可托天下。', explain: '得宠与受辱都让人惊慌，是因把外在评价看得比自身还重。我们之所以患得患失，正因执着于这个「我」。若能把对自身的看重，转为对天下人的担当，便值得托付天下。放下小我的得失，方能担起大任。' },
        { title: '第十四章', chapter: '第十四章', source: '《道德经》', text: '视之不见，名曰夷；听之不闻，名曰希；搏之不得，名曰微。此三者不可致诘，故混而为一。其上不皦，其下不昧。绳绳兮不可名，复归于无物。是谓无状之状，无物之象，是谓惚恍。迎之不见其首，随之不见其后。执古之道，以御今之有。能知古始，是谓道纪。', explain: '道看不见、听不到、摸不着，这三方面无从穷究，混然为一。它非明非暗，连绵不绝而归于虚无，是无形之形、无物之象，谓之惚恍。迎不见头，随不见尾。把握古已有之的道，用以驾驭当下的万有，便能通晓万物本始——这便是道的纲纪。' },
        { title: '第十五章', chapter: '第十五章', source: '《道德经》', text: '古之善为士者，微妙玄通，深不可识。夫唯不可识，故强为之容：豫兮若冬涉川；犹兮若畏四邻；俨兮其若客；涣兮其若释；敦兮其若朴；旷兮其若谷；混兮其若浊。孰能浊以静之徐清？孰能安以动之徐生？保此道者，不欲盈。夫唯不盈，故能蔽而新成。', explain: '古时得道之士，幽微深远难以描摹：审慎如冬日涉河，警觉如提防四邻，恭敬如做客，洒脱如冰释，淳厚如原木，空阔如山谷，浑厚如浊水。谁能于浑浊中静静澄清？谁能于安定中缓缓生发？守道者不求满盈，正因不盈，方能旧中出新、生生不息。' },
        { title: '第十六章', chapter: '第十六章', source: '《道德经》', text: '致虚极，守静笃。万物并作，吾以观复。夫物芸芸，各复归其根。归根曰静，静曰复命。复命曰常，知常曰明。不知常，妄作凶。知常容，容乃公，公乃全，全乃天，天乃道，道乃久，没身不殆。', explain: '把心灵虚寂到极点，把生活守静到笃定。看万物蓬勃生长，我从中观察它们循环往复、各归其根的规律。归根叫静，静叫复命，复命叫常——明白这常道才叫真明。不明常道而妄动必招凶险；明白常道便能包容、公正、周全，与天合道，终身无危。' },
        { title: '第十七章', chapter: '第十七章', source: '《道德经》', text: '太上，不知有之；其次，亲而誉之；其次，畏之；其次，侮之。信不足焉，有不信焉。悠兮其贵言。功成事遂，百姓皆谓：我自然。', explain: '最好的治理，百姓浑然不觉统治者的存在；其次，亲近而称颂；再次，畏惧；最下，轻侮。统治者的诚信不足，百姓便不再信任。高明的领导者惜言如金，事情成了，百姓都说「我们本来就该如此」。无为而治，是让人感觉不到被管理的最高境界。' },
        { title: '第十八章', chapter: '第十八章', source: '《道德经》', text: '大道废，有仁义；智慧出，有大伪；六亲不和，有孝慈；国家昏乱，有忠臣。', explain: '当大道被遗忘，才高倡仁义；当机巧被推崇，才生出巨大的虚伪；家人不和睦，才显出孝慈；国家陷昏乱，才捧出忠臣。这正是对一切「口号大于行动」的清醒洞见——越是呼唤某种德行，往往越是缺失。回归道的自然，德便无需标榜。' },
        { title: '第十九章', chapter: '第十九章', source: '《道德经》', text: '绝圣弃智，民利百倍；绝仁弃义，民复孝慈；绝巧弃利，盗贼无有。此三者以为文不足，故令有所属：见素抱朴，少私寡欲。', explain: '抛弃巧智的标榜，百姓得益百倍；放下仁义的教条，孝慈自然回归；戒除机巧贪利，盗贼自然消失。这三条作为条文仍嫌不足，须有根本的归属——那就是见守本真、抱持朴素、减少私心与欲望。简单不是贫乏，而是回归生命的本然。' },
        { title: '第二十章', chapter: '第二十章', source: '《道德经》', text: '绝学无忧。唯之与阿，相去几何？善之与恶，相去若何？人之所畏，不可不畏。荒兮，其未央哉！众人熙熙，如享太牢，如春登台。我独泊兮，其未兆；沌沌兮，如婴儿之未孩；傫傫兮，若无所归。众人皆有余，而我独若遗。我愚人之心也哉！俗人昭昭，我独昏昏。俗人察察，我独闷闷。澹兮其若海，飂兮若无止。众人皆有以，而我独顽且鄙。我独异于人，而贵食母。', explain: '弃绝世俗的机巧之学，便无牵绊之忧。应诺与呵斥相差几许？善恶的界限又在哪？世人都畏惧的，我也不得不畏。但众人热闹如赴宴、如登台，我却淡泊无兆，浑沌如婴儿、若无所归。众人样样有余，我独似有所失。我守的，是那生养万物的根本之道。' },
        { title: '第二十一章', chapter: '第二十一章', source: '《道德经》', text: '孔德之容，惟道是从。道之为物，惟恍惟惚。惚兮恍兮，其中有象；恍兮惚兮，其中有物。窈兮冥兮，其中有精；其精甚真，其中有信。自今及古，其名不去，以阅众甫。吾何以知众甫之状哉？以此。', explain: '大德之貌，完全随顺于道。道这个东西，恍惚难明：惚惚恍恍中，却有形象；恍恍惚惚中，却有实物；深远暗昧中，却有精微；那精微极真，内含诚信。从古至今，它的名从不消失，据此可观万物本始。我何以知万物之源？正是凭着这大道。' },
        { title: '第二十二章', chapter: '第二十二章', source: '《道德经》', text: '曲则全，枉则直，洼则盈，敝则新，少则得，多则惑。是以圣人抱一为天下式。不自见，故明；不自是，故彰；不自伐，故有功；不自矜，故长。夫唯不争，故天下莫能与之争。古之所谓「曲则全」者，岂虚言哉！诚全而归之。', explain: '委曲反能保全，弯曲反能伸直，低洼反能充盈，破旧反能更新，少取反有所得，贪多反致迷乱。圣人抱守大道，作为天下的范式：不自我标榜，反而显明；不自以为是，反而彰显；不夸耀，反而有功；不矜持，反而长久。正因不争，天下无人能与他争。' },
        { title: '第二十三章', chapter: '第二十三章', source: '《道德经》', text: '希言自然。故飘风不终朝，骤雨不终日。孰为此者？天地。天地尚不能久，而况于人乎？故从事于道者，同于道；德者，同于德；失者，同于失。同于道者，道亦乐得之；同于德者，德亦乐得之；同于失者，失亦乐得之。信不足焉，有不信焉。', explain: '少发号施令，才合自然。狂风刮不了一个早晨，骤雨下不了一整天——连天地都难以持久，何况人呢？所以修行要与道相合：同道者道乐于伴他，同德者德乐于随他，同失者失也乐于缠他。统治者诚信不足，百姓自然不信。同频相吸，因果自招。' },
        { title: '第二十四章', chapter: '第二十四章', source: '《道德经》', text: '企者不立，跨者不行。自见者不明，自是者不彰，自伐者无功，自矜者不长。其在道也，曰：余食赘形。物或恶之，故有道者不处。', explain: '踮脚站不稳，跨步走不远。自我表现者反不见真章，自以为是者反不被认可，自我夸耀者反没有功劳，自傲矜持者反不能长久。从道的角度看，这些都是剩饭赘瘤，惹人厌弃，所以有道之人绝不如此。谦退守拙，才是长久之道。' },
        { title: '第二十五章', chapter: '第二十五章', source: '《道德经》', text: '有物混成，先天地生。寂兮寥兮，独立而不改，周行而不殆，可以为天地母。吾不知其名，强字之曰道，强为之名曰大。大曰逝，逝曰远，远曰反。故道大，天大，地大，人亦大。域中有四大，而人居其一焉。人法地，地法天，天法道，道法自然。', explain: '有个浑然一体的东西，生于天地之前。它寂静空阔、独立长存、循环不息，堪称天地之母。我不知其名，勉强叫它道、叫它大。大则流逝，流逝则深远，深远则返本。域中有四大——道、天、地、人，人居其一。人取法地，地取法天，天取法道，道纯任自然。' },
        { title: '第二十六章', chapter: '第二十六章', source: '《道德经》', text: '重为轻根，静为躁君。是以圣人终日行不离辎重。虽有荣观，燕处超然。奈何万乘之主，而以身轻天下？轻则失根，躁则失君。', explain: '厚重是轻浮的根基，沉静是躁动的主宰。圣人终日行走也不离载粮的辎重（喻根本），纵有繁华在侧，也安处超然。奈何身为大国之君，却以轻率躁动对待天下？轻率会失根，躁动会失主。守住内在的厚重与沉静，方能不为外境所摇。' },
        { title: '第二十七章', chapter: '第二十七章', source: '《道德经》', text: '善行无辙迹，善言无瑕谪，善数不用筹策，善闭无关楗而不可开，善结无绳约而不可解。是以圣人常善救人，故无弃人；常善救物，故无弃物。是谓袭明。故善人者，不善人之师；不善人者，善人之资。不贵其师，不爱其资，虽智大迷，是谓要妙。', explain: '高明的行动不留痕迹，高明的话语无可指摘，高明的谋算不用筹码，高明的封闭不用门闩却打不开，高明的系结不用绳索却解不开。圣人总善于救人，故无人被弃；善于救物，故无物被弃——这叫承袭的光明。善人是不善人的老师，不善人是善人的借鉴。不尊师、不爱资，虽聪明也是大迷。这便是精微之妙。' },
        { title: '第二十八章', chapter: '第二十八章', source: '《道德经》', text: '知其雄，守其雌，为天下谿。为天下谿，常德不离，复归于婴儿。知其白，守其黑，为天下式。为天下式，常德不忒，复归于无极。知其荣，守其辱，为天下谷。为天下谷，常德乃足，复归于朴。朴散则为器，圣人用之，则为官长，故大制不割。', explain: '明知刚强，却安守柔雌，甘为天下的溪谷——常德不离，回归婴儿般的纯真。明知昭明，却安守暗昧，甘为天下的范式——常德无差，回归无极。明知荣耀，却安守卑辱，甘为天下的空谷——常德充盈，回归质朴。质朴散而为器物，圣人用此原则是百官之长，所以大制不割裂。以柔克刚，以退为进。' },
        { title: '第二十九章', chapter: '第二十九章', source: '《道德经》', text: '将欲取天下而为之，吾见其不得已。天下神器，不可为也，不可执也。为者败之，执者失之。是以圣人无为，故无败；无执，故无失。夫物或行或随，或歔或吹，或强或羸，或载或隳。是以圣人去甚，去奢，去泰。', explain: '想靠强力去夺取天下而有所作为，我看他终将落空。天下是神圣之物，不可妄为、不可把持。强为者必败，把持者必失。所以圣人无为，故无败；不执，故无失。万物各有性情——有的前行有的跟随，有的轻嘘有的急吹，有的强健有的羸弱，有的安载有的崩毁。圣人因此去除极端、奢侈与过度，守中而行。' },
        { title: '第三十章', chapter: '第三十章', source: '《道德经》', text: '以道佐人主者，不以兵强天下。其事好还。师之所处，荆棘生焉。大军之后，必有凶年。善有果而已，不敢以取强。果而勿矜，果而勿伐，果而勿骄，果而不得已，果而勿强。物壮则老，是谓不道，不道早已。', explain: '用道辅佐君主的人，不靠武力逞强于天下。用兵之事必遭报应——大军所到之处荆棘丛生，大战之后必逢荒年。善用兵者只求达到目的便止，不敢恃强。达目的不骄傲、不夸耀、不逞强，只因那是不得已。事物壮盛便走向衰老，这不合道，不合道便早早消亡。' },
        { title: '第三十一章', chapter: '第三十一章', source: '《道德经》', text: '夫兵者，不祥之器，物或恶之，故有道者不处。君子居则贵左，用兵则贵右。兵者不祥之器，非君子之器，不得已而用之，恬淡为上。胜而不美，而美之者，是乐杀人。夫乐杀人者，则不可得志于天下矣。吉事尚左，凶事尚右。偏将军居左，上将军居右，言以丧礼处之。杀人之众，以悲哀泣之，战胜以丧礼处之。', explain: '兵器是不祥之物，人人厌恶，有道者绝不亲近。君子平日以左为贵，用兵时以右为贵（凶位）。兵器非君子之器，不得已才用，以恬淡为尚。胜了也不值得赞美，赞美胜利的，是乐于杀人；乐于杀人者，不可能得志于天下。所以军事以丧礼对待：杀人众多，当以悲哀泣之；即便战胜，也以丧礼处之。' },
        { title: '第三十二章', chapter: '第三十二章', source: '《道德经》', text: '道常无名，朴虽小，天下莫能臣也。侯王若能守之，万物将自宾。天地相合，以降甘露，民莫之令而自均。始制有名，名亦既有，夫亦将知止，知止可以不殆。譬道之在天下，犹川谷之于江海。', explain: '道永恒无名，质朴虽微，天下却无人能臣服它。侯王若能守道，万物将自发归顺。天地交合降下甘露，无人命令而自然均匀。制度既立、名分已定，便当知止——知止才能免危。道在天下，正如川谷奔向江海，众流自然归往。守朴知止，天下自宾。' },
        { title: '第三十三章', chapter: '第三十三章', source: '《道德经》', text: '知人者智，自知者明。胜人者有力，自胜者强。知足者富。强行者有志。不失其所者久。死而不亡者寿。', explain: '了解别人是聪明，认识自己才是真明。战胜别人是有力，战胜自己才是真强。懂得满足便是富有。坚持不懈是有志。不丧失根本才能长久。身死而精神不灭，才是真正的长寿。这一章是全书的修身总纲——一切向外，不如向内。' },
        { title: '第三十四章', chapter: '第三十四章', source: '《道德经》', text: '大道泛兮，其可左右。万物恃之以生而不辞，功成而不有。衣养万物而不为主，可名于小；万物归焉而不为主，可名为大。以其终不自为大，故能成其大。', explain: '大道广泛流布，无所不在。万物靠它生长它从不推辞，功成却不占有；养育万物而不做主宰，可说它渺小；万物归附它仍不做主宰，可说它伟大。正因它始终不自以为大，反而成就了其伟大。无为、不宰、不居功——这是最伟大的力量。' },
        { title: '第三十五章', chapter: '第三十五章', source: '《道德经》', text: '执大象，天下往。往而不害，安平太。乐与饵，过客止。道之出口，淡乎其无味，视之不足见，听之不足闻，用之不足既。', explain: '持守大道，天下人皆来归往；归往而互不相害，于是安宁太平。音乐与美食，能让过客驻足；但道说出口，却淡而无味，看不够、听不清、用不尽。道的伟大不在感官的浓烈，而在那取之不尽、润物无声的深远力量。' },
        { title: '第三十六章', chapter: '第三十六章', source: '《道德经》', text: '将欲歙之，必固张之；将欲弱之，必固强之；将欲废之，必固兴之；将欲取之，必固与之。是谓微明。柔弱胜刚强。鱼不可脱于渊，国之利器不可以示人。', explain: '想要收敛它，必先暂且扩张它；想要削弱它，必先暂且增强它；想要废去它，必先暂且兴盛它；想要夺取它，必先暂且给予它。这叫微妙的明察。柔弱终胜刚强。鱼不可离开深潭，治国利器不可炫耀于人。洞察物极必反，方能以柔克刚、藏器于身。' },
        { title: '第三十七章', chapter: '第三十七章', source: '《道德经》', text: '道常无为而无不为。侯王若能守之，万物将自化。化而欲作，吾将镇之以无名之朴。无名之朴，夫亦将不欲。不欲以静，天下将自定。', explain: '道永远无为，却成就了一切。侯王若能守道，万物将自行化育。化育中若有人欲萌动，我便用无名之朴去镇服它。无名之朴，使人不起贪欲；不起贪欲而归于静，天下自然安定。无为不是不作为，而是不妄为、顺其自化。' },
        { title: '第三十八章', chapter: '第三十八章', source: '《道德经》', text: '上德不德，是以有德；下德不失德，是以无德。上德无为而无以为；下德无为而有以为。上仁为之而无以为；上义为之而有以为。上礼为之而莫之应，则攘臂而扔之。故失道而后德，失德而后仁，失仁而后义，失义而后礼。夫礼者，忠信之薄，而乱之首。前识者，道之华，而愚之始。是以大丈夫处其厚，不居其薄；处其实，不居其华。故去彼取此。', explain: '上德不标榜德，所以真有德；下德生怕失德，所以无德。上德无为且无心作为；下德无为却刻意作为。上仁有所为而无所图；上义有所为而有所图；上礼强为之而无人回应，便卷袖强拽。所以失道才讲德，失德才讲仁，失仁才讲义，失义才讲礼。礼是忠信浇薄、祸乱的开端。大丈夫立身厚重不居浇薄，守实不逐华。弃彼取此。' },
        { title: '第三十九章', chapter: '第三十九章', source: '《道德经》', text: '昔之得一者：天得一以清，地得一以宁，神得一以灵，谷得一以盈，万物得一以生，侯王得一以为天下贞。其致之也，谓天无以清，将恐裂；地无以宁，将恐废；神无以灵，将恐歇；谷无以盈，将恐竭；万物无以生，将恐灭；侯王无以贞，将恐蹶。故贵以贱为本，高以下为基。是以侯王自称孤、寡、不穀。此非以贱为本邪？非乎？故至誉无誉。是故不欲琭琭如玉，珞珞如石。', explain: '自古得「一」（道之纯一）的：天得一则清明，地得一则安宁，神得一则灵验，谷得一则充盈，万物得一则生长，侯王得一则成为天下典范。推而言之：天不清明将崩裂，地不安宁将荒废……所以贵以贱为根本，高以下为基础。侯王自称孤、寡、不穀，正是以贱为本。最高的声誉是无须称誉——不求如美玉般璀璨，宁可如顽石般坚实。' },
        { title: '第四十章', chapter: '第四十章', source: '《道德经》', text: '反者道之动，弱者道之用。天下万物生于有，有生于无。', explain: '循环往复，是道运行的方式；柔弱谦下，是道起用的方式。天下万物生于「有」，而「有」生于「无」。短短三句，道尽宇宙法则：物极必反、柔能克刚、无中生有。理解了「反」与「弱」，便懂得了道的动静之用。' },
        { title: '第四十一章', chapter: '第四十一章', source: '《道德经》', text: '上士闻道，勤而行之；中士闻道，若存若亡；下士闻道，大笑之。不笑不足以为道。故建言有之：明道若昧，进道若退，夷道若颣。上德若谷，大白若辱，广德若不足，建德若偷，质真若渝。大方无隅，大器晚成，大音希声，大象无形。道隐无名。夫唯道，善贷且成。', explain: '上等根器闻道，努力践行；中等将信将疑；下等大笑——不笑，倒显不出是道。古语说：光明的道似暗昧，前进的道似后退，平坦的道似崎岖；上德如空谷，大白如含辱，广德如不足，建德如偷惰，纯真如易变。大方无角，大器晚成，大音希声，大象无形。道幽隐无名，却唯有它，善于施与而成就万物。' },
        { title: '第四十二章', chapter: '第四十二章', source: '《道德经》', text: '道生一，一生二，二生三，三生万物。万物负阴而抱阳，冲气以为和。人之所恶，唯孤、寡、不穀，而王公以为称。故物或损之而益，或益之而损。人之所教，我亦教之。强梁者不得其死，吾将以为教父。', explain: '道生一，一生二（阴阳），二生三（阴阳和合之气），三生万物。万物背阴而抱阳，靠冲和之气达于和谐。人所厌恶的孤、寡、不穀，王公却用以自称。所以事物有时减损反得增益，增益反遭减损。前人教我的，我也用来教人：强横的人不得好死——我把这当作施教的根本。' },
        { title: '第四十三章', chapter: '第四十三章', source: '《道德经》', text: '天下之至柔，驰骋天下之至坚。无有入无间，吾是以知无为之有益。不言之教，无为之益，天下希及之。', explain: '天下最柔弱的东西，能穿透天下最坚硬的东西。无形的力量能进入没有缝隙之处，我由此懂得无为的益处。不言的教化、无为的益处，天下极少有人能及。柔、无、不言——这些看似最弱的力量，恰恰能攻克最坚固的屏障。' },
        { title: '第四十四章', chapter: '第四十四章', source: '《道德经》', text: '名与身孰亲？身与货孰多？得与亡孰病？甚爱必大费，多藏必厚亡。知足不辱，知止不殆，可以长久。', explain: '名声与身体，哪个更亲？身体与财物，哪个更重？获得与丧失，哪个更害？过分吝爱必致巨大耗费，过多囤积必致惨重损失。懂得满足便不受辱，懂得适可而止便不危殆，如此方能长久。外物皆为身外，惜身守分才是根本。' },
        { title: '第四十五章', chapter: '第四十五章', source: '《道德经》', text: '大成若缺，其用不弊。大盈若冲，其用不穷。大直若屈，大巧若拙，大辩若讷。躁胜寒，静胜热。清静为天下正。', explain: '最完满的似有欠缺，作用却永不衰败；最充盈的似空虚，作用却永不枯竭；最正直的似委屈，最灵巧的似笨拙，最善辩的似木讷。躁动能驱寒，宁静能消热。清静，才是天下的正道。大美不彰，大智若愚，守拙守静方为正。' },
        { title: '第四十六章', chapter: '第四十六章', source: '《道德经》', text: '天下有道，却走马以粪；天下无道，戎马生于郊。祸莫大于不知足，咎莫大于欲得。故知足之足，常足矣。', explain: '天下有道时，战马被退归田间施肥；天下无道时，怀驹的母马也得在郊野产崽（战乱不息）。祸患莫大于不知满足，过错莫大于贪得无厌。所以懂得「知足」的那种满足，才是永远的满足。减欲知足，是第一养生与治国之道。' },
        { title: '第四十七章', chapter: '第四十七章', source: '《道德经》', text: '不出户，知天下；不窥牖，见天道。其出弥远，其知弥少。是以圣人不行而知，不见而明，不为而成。', explain: '不出门，能知天下；不望窗外，能见天道。向外奔走得越远，认知反倒越少。所以圣人不必远行而能知，不必亲见而能明，不必妄为而能成。向内观照、契合大道，远胜向外追逐表象。心明了，天下事理自在其中。' },
        { title: '第四十八章', chapter: '第四十八章', source: '《道德经》', text: '为学日益，为道日损。损之又损，以至于无为。无为而无不为。取天下常以无事，及其有事，不足以取天下。', explain: '求学是天天增加知识，修道是天天减损欲望与成见。减了又减，终至无为。无为，便没有做不成的。治理天下常靠「不扰民」，一旦多事妄为，就不足以得天下。学问向外求，道向内损——放下越多，契合越深。' },
        { title: '第四十九章', chapter: '第四十九章', source: '《道德经》', text: '圣人无常心，以百姓心为心。善者吾善之，不善者吾亦善之，德善；信者吾信之，不信者吾亦信之，德信。圣人在天下，歙歙焉，为天下浑其心。百姓皆注其耳目，圣人皆孩之。', explain: '圣人没有固执的成见，以百姓的心为心。善良的我善待他，不善良的我也善待他，这叫德善；诚信的我信任他，不诚信的我也信任他，这叫德信。圣人立于天下，收敛含藏，使天下人的心归于浑朴。百姓都投注耳目于外，圣人却视如婴孩般护持。以善化不善，以信化不信。' },
        { title: '第五十章', chapter: '第五十章', source: '《道德经》', text: '出生入死。生之徒，十有三；死之徒，十有三；人之生，动之于死地，亦十有三。夫何故？以其生生之厚。盖闻善摄生者，陆行不遇兕虎，入军不被甲兵。兕无所投其角，虎无所措其爪，兵无所容其刃。夫何故？以其无死地。', explain: '人从生走向死。长寿的约占十分之三，短命的约占十分之三，本可长寿却妄动致死的也占十分之三。为何？因过分营厚其生。听说善于养生的人，陆行不遇犀虎，入军不被兵刃所伤——犀牛无处投角，猛虎无处下爪，兵器无处容刃。为何？因他从不把自己置于死地。养生之要，在避其妄动。' },
        { title: '第五十一章', chapter: '第五十一章', source: '《道德经》', text: '道生之，德畜之，物形之，势成之。是以万物莫不尊道而贵德。道之尊，德之贵，夫莫之命而常自然。故道生之，德畜之，长之育之，亭之毒之，养之覆之。生而不有，为而不恃，长而不宰，是谓玄德。', explain: '道生成万物，德养育万物，物赋予形态，势促成完成。所以万物无不尊道贵德。道之尊、德之贵，并非受命于谁，而是本然如此。道生养、培育、安定、滋养、庇护万物，却生而不占有、为而不恃靠、长而不宰制——这叫玄德。无为而无不包，是最高深的德。' },
        { title: '第五十二章', chapter: '第五十二章', source: '《道德经》', text: '天下有始，以为天下母。既得其母，以知其子；既知其子，复守其母，没身不殆。塞其兑，闭其门，终身不勤。开其兑，济其事，终身不救。见小曰明，守柔曰强。用其光，复归其明，无遗身殃，是为袭常。', explain: '天下有本始，作为万物之母。既得了母，便可知其子；既知其子，再守住母，终身无危。塞住感官的孔窍、关上欲望的门，终身不劳；打开孔窍、事事穷究，终身不可救药。能察见细微叫明，能守持柔弱叫强。运用外在的光，复归于内在的明，不给自己招灾——这叫承袭常道。' },
        { title: '第五十三章', chapter: '第五十三章', source: '《道德经》', text: '使我介然有知，行于大道，唯施是畏。大道甚夷，而人好径。朝甚除，田甚芜，仓甚虚；服文采，带利剑，厌饮食，财货有余，是谓盗夸。非道也哉！', explain: '假使我稍有见识，行走于大道，只怕误入邪路。大道本来平坦，世人却偏爱小径。你看：朝堂整洁，田野荒芜，粮仓空虚；而有人身着华服、腰佩利剑、厌食珍馐、财货有余——这叫盗魁的排场。这难道合于道吗！为政者当戒奢靡，行于平易之正道。' },
        { title: '第五十四章', chapter: '第五十四章', source: '《道德经》', text: '善建者不拔，善抱者不脱，子孙以祭祀不辍。修之于身，其德乃真；修之于家，其德乃余；修之于乡，其德乃长；修之于邦，其德乃丰；修之于天下，其德乃普。故以身观身，以家观家，以乡观乡，以邦观邦，以天下观天下。吾何以知天下然哉？以此。', explain: '善建根基的不可拔除，善抱持的不会脱落，子孙凭此祭祀不绝。修道于身，德便纯真；于家，德有余裕；于乡，德绵长；于国，德丰盛；于天下，德广普。所以以身观身、以家观家……以天下观天下。我何以知天下如此？正是凭这个道理。修身是齐家治国的起点。' },
        { title: '第五十五章', chapter: '第五十五章', source: '《道德经》', text: '含德之厚，比于赤子。蜂虿虺蛇不螫，猛兽不据，攫鸟不搏。骨弱筋柔而握固。未知牝牡之合而全作，精之至也。终日号而不嗄，和之至也。知和曰常，知常曰明。益生曰祥。心使气曰强。物壮则老，谓之不道，不道早已。', explain: '厚德之人，好比赤子。毒虫不蜇，猛兽不扑，凶鸟不抓。他筋骨柔弱却握得紧，不懂男女之事却小具勃发——精气至足；整日啼哭嗓不哑——和气至极。懂得和谐叫常，懂得常叫明。贪生纵欲叫灾殃，心气被欲望驱使叫逞强。物壮则老，这不合道，不合道便早早消亡。归朴守柔，方得长生。' },
        { title: '第五十六章', chapter: '第五十六章', source: '《道德经》', text: '知者不言，言者不知。塞其兑，闭其门，挫其锐，解其纷，和其光，同其尘，是谓玄同。故不可得而亲，不可得而疏；不可得而利，不可得而害；不可得而贵，不可得而贱。故为天下贵。', explain: '真知者不夸夸其谈，多言者并不真知。塞孔窍、闭门径、挫锋芒、解纷扰、涵敛光芒、混同尘世，这叫玄同。达到玄同之境，便不分亲疏、利害、贵贱——超然于一切对待之上。正因无所偏执，反被天下所贵。大智若愚，和光同尘。' },
        { title: '第五十七章', chapter: '第五十七章', source: '《道德经》', text: '以正治国，以奇用兵，以无事取天下。吾何以知其然哉？以此：天下多忌讳，而民弥贫；民多利器，国家滋昏；人多伎巧，奇物滋起；法令滋彰，盗贼多有。故圣人云：我无为而民自化，我好静而民自正，我无事而民自富，我无欲而民自朴。', explain: '以清正治国，以奇变用兵，以不扰民取天下。为何如此？请看：禁忌越多，百姓越穷；民间利器越多，国家越昏乱；机巧越多，怪事越生；法令越繁，盗贼越多。所以圣人说：我无为，民自化育；我好静，民自端正；我无事，民自富裕；我无欲，民自淳朴。少管束，多自在。' },
        { title: '第五十八章', chapter: '第五十八章', source: '《道德经》', text: '其政闷闷，其民淳淳；其政察察，其民缺缺。祸兮福之所倚，福兮祸之所伏。孰知其极？其无正也。正复为奇，善复为妖。人之迷，其日固久。是以圣人方而不割，廉而不刿，直而不肆，光而不耀。', explain: '政令宽厚，百姓反而淳朴；政令严苛，百姓反而狡黠。祸里倚伏着福，福里潜伏着祸。谁能知那终极？本无定准。正会转为奇，善会变为妖。人们的迷惑，由来已久。所以圣人方正而不生硬，有棱而不伤人，直率而不放肆，有光而不刺眼。守中道，不极端。' },
        { title: '第五十九章', chapter: '第五十九章', source: '《道德经》', text: '治人事天，莫若啬。夫唯啬，是谓早服；早服谓之重积德；重积德则无不克；无不克则莫知其极；莫知其极，可以有国；有国之母，可以长久。是谓深根固柢，长生久视之道。', explain: '治理人事、顺应天道，莫过于「啬」（爱惜、收敛）。唯其啬，叫早作准备；早预备叫厚积德；厚积德则无往不胜；无往不胜则莫测其极；莫测其极，便可治国；掌握治国之本，方能长久。这便是深根固柢、长生久视之道。惜力、藏锋、积德，是长治久安的根。' },
        { title: '第六十章', chapter: '第六十章', source: '《道德经》', text: '治大国，若烹小鲜。以道莅天下，其鬼不神；非其鬼不神，其神不伤人；非其神不伤人，圣人亦不伤人。夫两不相伤，故德交归焉。', explain: '治理大国，如同煎小鱼——不可频繁翻动。以道临天下，鬼怪便不显灵；非鬼不灵，而是那灵不伤人；非仅灵不伤人，圣人也不伤人。两者互不伤害，德行便交相归聚。为政贵在清静不扰，顺其自然，则上下皆安。' },
        { title: '第六十一章', chapter: '第六十一章', source: '《道德经》', text: '大邦者下流，天下之牝，天下之交也。牝常以静胜牡，以静为下。故大邦以下小邦，则取小邦；小邦以下大邦，则取大邦。故或下以取，或下而取。大邦不过欲兼畜人，小邦不过欲入事人。夫两者各得所欲，大者宜为下。', explain: '大国当如江河下流，处在天下雌静之交会处。雌常以静定胜雄，因静而处下。所以大国对小国谦下，便能聚拢小国；小国对大国谦下，便能见容于大国。或主动谦下以聚人，或谦下以见容。大国不过想统领，小国不过想依附。两者各遂所愿，但大国更宜处下。谦下，是汇纳天下的智慧。' },
        { title: '第六十二章', chapter: '第六十二章', source: '《道德经》', text: '道者，万物之奥。善人之宝，不善人之所保。美言可以市尊，美行可以加人。人之不善，何弃之有？故立天子，置三公，虽有拱璧以先驷马，不如坐进此道。古之贵此道者何？不曰以求得，有罪以免邪？故为天下贵。', explain: '道是万物的深藏之处。它是善人的珍宝，也是不善人得以保全的依托。美言可换尊重，美行可加于人。人纵有不善，道又何曾弃他？所以立天子、设三公，虽有拱璧驷马的厚礼，不如静坐进献此道。古人贵道，岂不因「有求可得、有罪可免」？故道为天下所贵。道普救一切，不弃一人。' },
        { title: '第六十三章', chapter: '第六十三章', source: '《道德经》', text: '为无为，事无事，味无味。大小多少，报怨以德。图难于其易，为大于其细。天下难事，必作于易；天下大事，必作于细。是以圣人终不为大，故能成其大。夫轻诺必寡信，多易必多难。是以圣人犹难之，故终无难矣。', explain: '以无为去作为，以无事去处事，以无味去品味。大化小、多化少，用德回报怨恨。攻克困难要从容易处入手，成就大事要从细微处做起。天下难事必起于易，大事必始于细。所以圣人始终不标榜「大」，反能成就大。轻易许诺必少信用，把易事看难，终无难事。慎始敬细。' },
        { title: '第六十四章', chapter: '第六十四章', source: '《道德经》', text: '其安易持，其未兆易谋。其脆易泮，其微易散。为之于未有，治之于未乱。合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下。为者败之，执者失之。是以圣人无为故无败，无执故无失。民之从事，常于几成而败之。慎终如始，则无败事。是以圣人欲不欲，不贵难得之货；学不学，复众人之所过，以辅万物之自然而不敢为。', explain: '局面安稳时易持守，征兆未现时易谋划；脆弱时易消解，微小时易打散。要在祸未生时处置，乱未起时治理。合抱大树生于毫末，九层高台起于垒土，千里远行始于足下。强为者败，把持者失；圣人无为故不败，不执故不失。人常于将成时失败——慎终如始，则无败事。圣人求众人所不求，学众人所不学，以辅万物自然而不敢妄为。' },
        { title: '第六十五章', chapter: '第六十五章', source: '《道德经》', text: '古之善为道者，非以明民，将以愚之。民之难治，以其智多。故以智治国，国之贼；不以智治国，国之福。知此两者亦稽式。常知稽式，是谓玄德。玄德深矣，远矣，与物反矣，然后乃至大顺。', explain: '古时善于行道者，不是教百姓机巧聪明，而是使他们返朴淳厚。百姓难治，正因智巧太多。用智巧治国，是国家的祸害；不用智巧治国，是国家的福分。懂得这两者便是法则。常守此法则，叫玄德。玄德深幽悠远，与世俗相反，而后达于最大的顺遂。大智若愚，返朴则治。' },
        { title: '第六十六章', chapter: '第六十六章', source: '《道德经》', text: '江海之所以能为百谷王者，以其善下之，故能为百谷王。是以圣人欲上民，必以言下之；欲先民，必以身后之。是以圣人处上而民不重，处前而民不害。是以天下乐推而不厌。以其不争，故天下莫能与之争。', explain: '江海所以能成为百川之王，因它善于处下，故百川归往。所以圣人想居于民上，必以言语谦下；想走在民前，必把自身退后。如此处上位而民不感重压，处前位而民不以为害，天下乐于推举而不厌弃。正因不争，天下无人能与他争。谦下，是汇聚众流的根本。' },
        { title: '第六十七章', chapter: '第六十七章', source: '《道德经》', text: '天下皆谓我道大，似不肖。夫唯大，故似不肖。若肖，久矣其细也夫！我有三宝，持而保之：一曰慈，二曰俭，三曰不敢为天下先。慈故能勇，俭故能广，不敢为天下先，故能成器长。今舍慈且勇，舍俭且广，舍后且先，死矣！夫慈，以战则胜，以守则固。天将救之，以慈卫之。', explain: '天下都说我的道太大，不像任何具体事物。正因大，才不像。若像，早就显得渺小了！我有三宝持守：一慈，二俭，三不敢为天下先。慈故能勇，俭故能广，不敢为先故能成众长。如今舍慈求勇、舍俭求广、舍后求先，必死！慈，用于战则胜、守则固。天要救助谁，便以慈护佑他。' },
        { title: '第六十八章', chapter: '第六十八章', source: '《道德经》', text: '善为士者不武，善战者不怒，善胜敌者不与，善用人者为之下。是谓不争之德，是谓用人之力，是谓配天古之极。', explain: '善做将帅的不逞勇武，善作战的不被激怒，善胜敌的不与硬拼，善用人的甘居人下。这叫不争的德，叫借助众人之力的智慧，叫契合天道古来的至高准则。真正的强大，是无须对抗的从容。' },
        { title: '第六十九章', chapter: '第六十九章', source: '《道德经》', text: '用兵有言：吾不敢为主，而为客；不敢进寸，而退尺。是谓行无行，攘无臂，扔无敌，执无兵。祸莫大于轻敌，轻敌几丧吾宝。故抗兵相若，哀者胜矣。', explain: '用兵者说：我不敢主动进攻，宁为防守之客；不敢前进一寸，宁退后一尺。这叫行动如无形、奋臂如无臂、迎敌如无敌、执兵如无兵。祸莫大于轻敌，轻敌几乎丧我三宝。所以两军相当，怀着哀悯之心（不得已而应战）的一方必胜。慈悲之师，不可战胜。' },
        { title: '第七十章', chapter: '第七十章', source: '《道德经》', text: '吾言甚易知，甚易行。天下莫能知，莫能行。言有宗，事有君。夫唯无知，是以不我知。知我者希，则我者贵。是以圣人被褐而怀玉。', explain: '我的话极易懂、极易行，天下却无人能懂、无人能行。言论有宗旨，行事有主脑。正因人们无知于道，所以不懂我。懂我的人稀少，效法我的人更珍贵。所以圣人外披粗衣、内怀美玉。真理往往朴素，不张扬于外。' },
        { title: '第七十一章', chapter: '第七十一章', source: '《道德经》', text: '知不知，尚矣；不知知，病也。圣人不病，以其病病。夫唯病病，是以不病。', explain: '知道自己有所不知，是上等的；不知却自以为知，是弊病。圣人没有这弊病，因他把「不知而强以为知」当作病来警惕。正因把此病当病，所以终无此病。诚实面对自己的无知，才是真知的开始。' },
        { title: '第七十二章', chapter: '第七十二章', source: '《道德经》', text: '民不畏威，则大威至。无狎其所居，无厌其所生。夫唯不厌，是以不厌。是以圣人自知不自见，自爱不自贵。故去彼取此。', explain: '百姓若不畏惧威压，更大的祸乱就要降临。不要侵逼百姓的居所，不要压制他们的生计。正因不压迫，才不会遭人厌弃。所以圣人自知己能而不自我标榜，自爱其身而不自居高贵。弃彼取此——收敛，方得安稳。' },
        { title: '第七十三章', chapter: '第七十三章', source: '《道德经》', text: '勇于敢则杀，勇于不敢则活。此两者，或利或害。天之所恶，孰知其故？是以圣人犹难之。天之道，不争而善胜，不言而善应，不召而自来，繟然而善谋。天网恢恢，疏而不失。', explain: '勇于逞强则招杀，勇于示弱则得活。二者一利一害。天所厌恶的，谁能知其中缘故？连圣人也难言尽。天道不争而善于取胜，不言语而善于回应，不召唤而万物自来，从容而善于谋划。天网广大，虽稀疏却无一遗漏。顺势守柔，天道自佑。' },
        { title: '第七十四章', chapter: '第七十四章', source: '《道德经》', text: '民不畏死，奈何以死惧之？若使民常畏死，而为奇者，吾得执而杀之，孰敢？常有司杀者杀。夫代司杀者杀，是谓代大匠斫。夫代大匠斫者，希有不伤其手矣。', explain: '百姓若不怕死，用死来恐吓又有何用？若百姓真怕死，对作乱者我抓来杀掉，谁还敢？但自有专司杀伐的天道去杀。代替天道去杀人，如同代替大匠去砍木——代大匠砍的，很少不伤自己的手。为政者当知敬畏，不滥施杀罚。' },
        { title: '第七十五章', chapter: '第七十五章', source: '《道德经》', text: '民之饥，以其上食税之多，是以饥。民之难治，以其上之有为，是以难治。民之轻死，以其上求生之厚，是以轻死。夫唯无以生为者，是贤于贵生。', explain: '百姓饥馑，因统治者搜刮赋税太重；百姓难治，因统治者妄加干预；百姓轻生冒死，因统治者奢养自身太过。所以那些不把一己生计看得过重的人，反而胜过过于厚养自身的人。少剥削、少扰民、薄私奉，才是长治久安。' },
        { title: '第七十六章', chapter: '第七十六章', source: '《道德经》', text: '人之生也柔弱，其死也坚强。草木之生也柔脆，其死也枯槁。故坚强者死之徒，柔弱者生之徒。是以兵强则灭，木强则折。强大处下，柔弱处上。', explain: '人活着时身体柔弱，死后变得僵硬；草木生长时柔脆，死时枯槁。所以坚强属于死的一类，柔弱属于生的一类。因此军队逞强则覆灭，树木强硬则摧折。强大反而居下，柔弱反而居上。柔弱，是生生之机的体现。' },
        { title: '第七十七章', chapter: '第七十七章', source: '《道德经》', text: '天之道，其犹张弓与？高者抑之，下者举之；有余者损之，不足者补之。天之道，损有余而补不足。人之道则不然，损不足以奉有余。孰能有余以奉天下？唯有道者。是以圣人为而不恃，功成而不处，其不欲见贤。', explain: '天道岂不像张弓？高了压低，低了抬高；多余的减损，不足的补充。天道损有余以补不足；人道却相反，损不足以奉有余。谁能把有余献给天下？唯有得道者。所以圣人作为而不倚靠、功成而不居处，不愿显露贤能。效法天道之均平，才是至公。' },
        { title: '第七十八章', chapter: '第七十八章', source: '《道德经》', text: '天下莫柔弱于水，而攻坚强者莫之能胜，以其无以易之。弱之胜强，柔之胜刚，天下莫不知，莫能行。是以圣人云：受国之垢，是谓社稷主；受国不祥，是为天下王。正言若反。', explain: '天下没有比水更柔弱的，但攻坚克强却无人能胜它，因它无可替代的柔韧。弱胜强、柔胜刚，天下无人不知，却无人能行。所以圣人说：能承受国家的屈辱，才配做社稷之主；能承担国家的灾殃，才配做天下之王。正理听来，却像反话。' },
        { title: '第七十九章', chapter: '第七十九章', source: '《道德经》', text: '和大怨，必有余怨，安可以为善？是以圣人执左契，而不责于人。有德司契，无德司彻。天道无亲，常与善人。', explain: '强行调和深仇，必留余怨，怎算妥善？所以圣人虽执债权契约，却不向人逼讨。有德者像执契而不责人，无德者像税官般苛索。天道没有亲疏，却总佑助善人。不结怨、不苛责、以宽待人，方合天道。' },
        { title: '第八十章', chapter: '第八十章', source: '《道德经》', text: '小国寡民。使有什伯之器而不用，使民重死而不远徙。虽有舟舆，无所乘之；虽有甲兵，无所陈之。使民复结绳而用之。甘其食，美其服，安其居，乐其俗。邻国相望，鸡犬之声相闻，民至老死，不相往来。', explain: '理想之境：国家小、人口少。纵有精巧器具也不使用，百姓看重生命不远迁。虽有船车无须乘坐，虽有甲兵无须陈列。让百姓回到结绳记事的淳朴。吃得香甜、穿得漂亮、住得安适、习俗和乐。邻国相望、鸡犬相闻，百姓直到老死也不相往来（各安其生）。这是返朴安居的图景。' },
        { title: '第八十一章', chapter: '第八十一章', source: '《道德经》', text: '信言不美，美言不信。善者不辩，辩者不善。知者不博，博者不知。圣人不积，既以为人，己愈有；既以与人，己愈多。天之道，利而不害；圣人之道，为而不争。', explain: '真话不华美，华美的话不真。良善者不巧辩，巧辩者不良善。真知者不炫耀广博，炫耀广博者非真知。圣人不囤积，越奉献给人，自己越充实；越给予别人，自己越丰盈。天之道，利物而不害物；圣人之道，作为而不争夺。全书以此作结——无私，方为大成。' }
      ],

      vajra: [
        { title: '应无所住', chapter: '第十品', source: '《金刚经》', text: '应无所住而生其心。', explain: '心不执着于任何外境，方能生起清净智慧。修行的要点不是压抑念头，而是不黏着、不追逐，如雁过长空，影沉寒水。' },
        { title: '一切有为法', chapter: '第三十二品', source: '《金刚经》', text: '一切有为法，如梦幻泡影，如露亦如电，应作如是观。', explain: '世间一切因缘和合而生的事物，都如梦、如幻、如泡影、如露、如电，转瞬即逝。以这样的眼光看待得失，心便不易被外境牵动。' },
        { title: '无我相', chapter: '第十四品', source: '《金刚经》', text: '无我相，无人相，无众生相，无寿者相。', explain: '不执着自我的形象，也不执着他人、众生、寿命的分别。放下“我”的边界，才能减少对立与烦恼，体会到更宽广的慈悲。' },
        { title: '法尚应舍', chapter: '第六品', source: '《金刚经》', text: '法尚应舍，何况非法。', explain: '连正确的法门都应当放下，更不必说不正确的执着。方法是指月之手，目的是觉醒。不要在工具上停留，而要指向真正的内心自由。' },
        { title: '凡所有相', chapter: '第五品', source: '《金刚经》', text: '凡所有相，皆是虚妄。若见诸相非相，即见如来。', explain: '一切有形之相皆虚妄不实。能透过表象看见那无相的本体，便见到了如来——不是某个神，而是万法背后的清净实相。' },
        { title: '三心不可得', chapter: '第十八品', source: '《金刚经》', text: '过去心不可得，现在心不可得，未来心不可得。', explain: '心念念念迁流，过去已灭、未来未生、现在即逝，三心皆了不可得。执着于某个念头，如同想抓住流水，徒劳而已。' },
        { title: '如来者', chapter: '第二十九品', source: '《金刚经》', text: '如来者，无所从来，亦无所去，故名如来。', explain: '如来不是从某处来、到某处去的实体，而是“如实而来”的觉性本身。来去是相，觉性不动，故名如来。' },
        { title: '若以色见', chapter: '第二十六品', source: '《金刚经》', text: '若以色见我，以音声求我，是人行邪道，不能见如来。', explain: '若以为拜个金身、念几句咒就能见佛，那便落了外相。真正的佛是觉性，向外求索反而是背离。' },
        { title: '无住行施', chapter: '第四品', source: '《金刚经》', text: '菩萨于法，应无所住行于布施。', explain: '行善布施却不执着“我在施、施于谁、施了什么”，三轮体空。这样的功德如虚空不可称量，才是清净的给予。' },
        { title: '七宝布施', chapter: '第八品', source: '《金刚经》', text: '若人满三千大千世界七宝以用布施，其福德不如受持此经四句偈。', explain: '财施再多也有尽，法施一念能破迷。一句般若胜却堆积如山的珍宝，因为法是解脱的种子。' },
        { title: '说法者', chapter: '第二十一品', source: '《金刚经》', text: '说法者，无法可说，是名说法。', explain: '真正说法的人，知道实相本不可说，所谓说法只是方便引导。执著有法可说，反而迷了。' },
        { title: '身相见否', chapter: '第五品', source: '《金刚经》', text: '可以身相见如来不？不也，世尊。如来不应以具足色身见。', explain: '佛的圆满不在三十二相好，而在无相的觉性。执着庄严形貌去寻佛，犹如缘木求鱼。' },
        { title: '无为差别', chapter: '第七品', source: '《金刚经》', text: '一切贤圣，皆以无为法而有差别。', explain: '贤圣之分不在神通高低，而在契合无为法的深浅。越不造作、越贴近本然，境界越高。' }
      ],
      neijing: [
        { title: '法于阴阳', chapter: '上古天真论', source: '《黄帝内经》', text: '法于阴阳，和于术数，食饮有节，起居有常，不妄作劳。', explain: '养生要效法天地阴阳的变化，调和身心术数，饮食有节制，作息有规律，不妄自劳累。看似简单的道理，却是健康长寿的根本。' },
        { title: '正气存内', chapter: '刺法论', source: '《黄帝内经》', text: '正气存内，邪不可干。', explain: '人体自身的正气充足，外邪就难以入侵。不仅是身体，心理亦然：内心清明坚定，外界的干扰自然减少。' },
        { title: '春夏养阳', chapter: '四气调神大论', source: '《黄帝内经》', text: '春夏养阳，秋冬养阴。', explain: '春夏季节宜养护阳气，宜早起、多动、舒展；秋冬宜滋养阴精，宜早睡、少耗、收敛。顺应四时，是中医养生的核心原则。' },
        { title: '形神合一', chapter: '素问', source: '《黄帝内经》', text: '形与神俱，而尽终其天年。', explain: '身体与心神和谐统一，才能尽享天年。现代人常忽视情绪对身体的伤害，修身养性正是让形与神重新合一。' },
        { title: '心者君主', chapter: '灵兰秘典', source: '《黄帝内经》', text: '心者，君主之官也，神明出焉。', explain: '心如同一国之君，主宰精神意识。心神安宁，则五脏六腑各安其位；心乱则百症蜂起。养生先养心，此其一也。' },
        { title: '肝者将军', chapter: '灵兰秘典', source: '《黄帝内经》', text: '肝者，将军之官，谋虑出焉。', explain: '肝如将军，主谋略、主疏泄。情绪郁结最伤肝，故养肝重在舒展情志、少生闷气。' },
        { title: '肾者作强', chapter: '灵兰秘典', source: '《黄帝内经》', text: '肾者，作强之官，伎巧出焉。', explain: '肾藏精、主骨生髓，关乎精力与智慧。节欲保精、不妄耗，是体力与脑力长盛的根基。' },
        { title: '上工治未病', chapter: '四气调神大论', source: '《黄帝内经》', text: '是故圣人不治已病治未病，不治已乱治未乱。', explain: '高明的医者，在疾病未成形时便调摄防范。与其病后求医，不如日常养正——预防远胜于治疗。' },
        { title: '阴平阳秘', chapter: '生气通天论', source: '《黄帝内经》', text: '阴平阳秘，精神乃治；阴阳离决，精气乃绝。', explain: '阴阳平衡协调，精神便安和；一旦阴阳决裂离析，精气随之断绝。平衡二字，是养生的总纲。' },
        { title: '阳气如日', chapter: '生气通天论', source: '《黄帝内经》', text: '阳气者，若天与日，失其所则折寿而不彰。', explain: '人身的阳气如同天上的太阳，失其本位便寿命减损、光彩不彰。保暖、少耗、避寒，皆是护阳之道。' },
        { title: '五志所伤', chapter: '阴阳应象大论', source: '《黄帝内经》', text: '怒伤肝，喜伤心，思伤脾，悲伤肺，恐伤肾。', explain: '过激的情绪会伤及对应脏腑。所谓“病由心生”，调畅情志便是服药——心平，则五脏安。' },
        { title: '四气调神', chapter: '四气调神大论', source: '《黄帝内经》', text: '春三月，此谓发陈，天地俱生，万物以荣，夜卧早起，广步于庭。', explain: '春季是生发之季，宜早睡早起、缓步庭院，让身体随万物一同舒展。顺时而动，是与天地同频的养生。' },
        { title: '女子七岁', chapter: '上古天真论', source: '《黄帝内经》', text: '女子七岁肾气盛，齿更发长；七七任脉虚，太冲脉衰少。', explain: '女子生命以“七”为节律，肾气盛衰主导发育与衰老。了解自身节律，便知何时养、何时藏。' }
      ],
      zhongyi: [
        { title: '气血流通', chapter: '养生总则', source: '中医养生', text: '气血流通，百病不生。', explain: '气血是生命活动的物质基础。气行则血行，气滞则血瘀。通过运动、呼吸、情志调节，让气血畅通，自然少生病痛。' },
        { title: '药食同源', chapter: '食疗篇', source: '中医养生', text: '五谷为养，五果为助，五畜为益，五菜为充。', explain: '谷物是养生的根本，水果是辅助，肉类是补益，蔬菜是充实。饮食多样化、以植物为主，与现代营养学不谋而合。' },
        { title: '子时熟睡', chapter: '子午流注', source: '中医养生', text: '子时一阳生，胆气始旺，宜熟睡以养少阳。', explain: '晚上 11 点至凌晨 1 点是子时，阳气初生，胆经当令。此时熟睡，有助于阳气生发和肝胆排毒，是最经济的养生法。' },
        { title: '恬淡虚无', chapter: '情志养生', source: '中医养生', text: '恬淡虚无，真气从之；精神内守，病安从来。', explain: '心境淡泊宁静，真气自然顺畅；精神内守而不外耗，疾病又从何而生？情绪稳定，是最高级的养生。' },
        { title: '五劳所伤', chapter: '宣明五气', source: '中医养生', text: '久视伤血，久卧伤气，久坐伤肉，久立伤骨，久行伤筋。', explain: '任何姿态过久都会成伤。用电脑要起身，卧床莫贪懒，站立需轮换，行走知歇息——动静有节，方护周身。' },
        { title: '胃不和卧不安', chapter: '逆调论', source: '中医养生', text: '胃不和则卧不安。', explain: '脾胃壅滞、食积不化，最扰睡眠。晚饭宜少、宜淡、宜早，给肠胃留足运化的时间，夜寐才安稳。' },
        { title: '心主血脉', chapter: '五脏生成', source: '中医养生', text: '心主血脉，其华在面。', explain: '心的状态显于面色。面色红润有光，是心血充盈；苍白或晦暗，常提示心气不足。养面先养心。' },
        { title: '脾主运化', chapter: '经脉别论', source: '中医养生', text: '脾主运化，为后天之本。', explain: '脾将饮食化为气血精微，是后天滋养的源头。饮食有节、忌生冷黏腻，便是护好这“后天之本”。' },
        { title: '肝主疏泄', chapter: '病机', source: '中医养生', text: '肝主疏泄，喜条达而恶抑郁。', explain: '肝负责气机调畅，最怕压抑郁结。舒展胸怀、适度宣泄，让肝气条达，身心才松快。' },
        { title: '肾主藏精', chapter: '六节藏象', source: '中医养生', text: '肾主藏精，为先天之本。', explain: '肾藏先天之精，关乎生长、发育、生殖与衰老。节欲、保暖、少熬夜，是护肾三宝。' },
        { title: '春捂秋冻', chapter: '四时调摄', source: '中医养生', text: '春捂秋冻，不生杂病。', explain: '初春莫急减衣，让阳气缓缓外达；初秋莫急添衣，让身体渐耐寒寒。顺应寒热渐变，腠理自固。' },
        { title: '寒从足起', chapter: '养生谚语', source: '中医养生', text: '寒从足下生，病从口中入。', explain: '足部离心脏最远、最易受寒，护脚即是护阳；饮食不节、生冷无度，则病从口入。两端最当留意。' },
        { title: '养生先养心', chapter: '养生总则', source: '中医养生', text: '养生先养心，心平气和百脉通。', explain: '所有养生法门，皆以心平为基。心若焦躁，补药也难吸收；心若安宁，谷气自能化生气血。' }
      ],
      guiguzi: [
        { title: '捭阖之道', chapter: '捭阖第一', source: '《鬼谷子》', text: '捭阖者，道之大化，说之变也。必豫审其变化。', explain: '捭是开启、是表达，阖是闭合、是缄默。开口与静观，是游说与处世的两种根本力量。懂得在何时言说、何时收束，便能把握人心与事态的流转。于内修而言，也是一种张弛有度的节奏：收放自如，方得从容。' },
        { title: '反以知古', chapter: '反应第二', source: '《鬼谷子》', text: '反以观往，覆以验来；反以知古，覆以知今。', explain: '回头考察过去，用来验证将来；反思古代，用来理解当下。鬼谷子极重“反复”的功夫——让信息在来回回应中显出真相。修行人亦可借回顾自省，照见自己的成长与盲区。' },
        { title: '内揵', chapter: '内揵第三', source: '《鬼谷子》', text: '欲说者务隐度，计事者务循顺。', explain: '想说服别人，要先暗中揣度对方心意；谋划事情，要顺着情理自然推进。这是在教我们：真正的智慧不是强求，而是先理解、再顺势。待人接物若能以对方为起点，关系便通畅无碍。' },
        { title: '揣情', chapter: '揣篇', source: '《鬼谷子》', text: '揣情者，必以其甚喜之时，往而极其欲也；其有欲也，不能隐其情。', explain: '揣摩人心，要在对方最欢喜、欲望最盛时去体会——此时真情难以隐藏。鬼谷子把“识人”变成一门可习的技艺。于修身而言，认识自己亦需在对境起念时观照，方能看清本心的真实取向。' },
        { title: '粤若稽古', chapter: '捭阖第一', source: '《鬼谷子》', text: '粤若稽古，圣人之在天地间也，为众生之先。', explain: '考察古往，圣人居于天地之间，总能先一步洞察时势、引领众人。先觉者不靠运气，而靠对规律的静观与体认。' },
        { title: '抵巇', chapter: '抵巇第四', source: '《鬼谷子》', text: '物有自然，事有离合。有近而不可见，有远而可知。', explain: '事物本有自然的裂痕与聚散。有些裂痕近在眼前却被忽视，有些遥远反而能推知。察觉细微的“巇”（缝隙），方能及时修补或顺势而为。' },
        { title: '飞箝', chapter: '飞箝第五', source: '《鬼谷子》', text: '引钩箝之辞，飞而箝之。', explain: '先以褒扬（飞）投其所好、让其敞开心扉，再顺势加以掌控引导（箝）。此法用于识人，也可反观：莫因几句好话便乱了方寸。' },
        { title: '忤合', chapter: '忤合第六', source: '《鬼谷子》', text: '凡趋合倍反，计有适合。化转环属，各有形势。', explain: '该靠拢还是该背离，全看情势是否相宜。世事如环，转化无定，审时度势者方能立于不败。固执一端，反失其机。' },
        { title: '摩篇', chapter: '摩篇第八', source: '《鬼谷子》', text: '摩之在此，符之在彼；从而应之，事无不可。', explain: '在此处揣摩试探，彼处便有相应的回应显形。顺着回响去应对，几乎没有办不成的事。这是“观察—反馈”的辩证智慧。' },
        { title: '权篇', chapter: '权篇第九', source: '《鬼谷子》', text: '故与智者言，依于博；与博者言，依于辨；与辨者言，依于要。', explain: '对智者谈广度，对博学者谈思辨，对善辩者谈要领。说话要因人而变、投其所重，方能入心。沟通的本质是“对症”，不是“对稿”。' },
        { title: '谋篇', chapter: '谋篇第十', source: '《鬼谷子》', text: '凡谋有道，必得其所因，以求其情。', explain: '谋划自有其法：必先弄清事情的起因与本根，才能探得实情、定下良策。不明“因”而妄谋，如同无根之木。' },
        { title: '决篇', chapter: '决篇第十一', source: '《鬼谷子》', text: '危而美名者，可则决之；不用费力而易成者，可则决之。', explain: '该决断时：于公有利、于名无亏者可决；不费力气便易成者也可决。优柔寡断最耗心神，审机而断，是成事的关键。' },
        { title: '养志', chapter: '养志法灵龟', source: '《鬼谷子》', text: '养志之始，务在安己；己安则志意实坚。', explain: '养护心志，先要让自己安定下来。内心安顿，志向才坚实不可夺。一切外求之前，先安顿好这颗心。' }
      ],
      yinfujing: [
        { title: '观天之道', chapter: '上篇', source: '《阴符经》', text: '观天之道，执天之行，尽矣。', explain: '观察天地自然的运行规律，并按照这个规律去行动，就足够了。这短短十个字，是整部《阴符经》的总纲——天人合一不是空谈，而是切实可行的修行路径。' },
        { title: '天人合发', chapter: '上篇', source: '《阴符经》', text: '天人合发，万化定基。', explain: '天道与人道相合而发动，万物变化的根基便由此确定。修行人若能将自己的节律与天地同步，便能借天地之力成就自身，此即“盗机”之正用。' },
        { title: '心生于物', chapter: '中篇', source: '《阴符经》', text: '心生于物，死于物，机在于目。', explain: '心因外物而生起执着，也因外物而陷溺消亡；关键在于你用什么眼光去看它。“机在于目”——觉悟的契机就在你如何看待万物的那一刻。' },
        { title: '知之修练', chapter: '下篇', source: '《阴符经》', text: '圣人知自然之道不可违，因而制之。', explain: '圣人明白自然规律不可违背，于是顺应它、节制自己。不是征服自然，而是与之和谐共处。修身亦然：不与本性对抗，而是引导它回归正道。' },
        { title: '天性人心', chapter: '上篇', source: '《阴符经》', text: '天性，人也；人心，机也。立天之道，以定人也。', explain: '天之性即人之性，人心是那灵动的机枢。确立了天道的准则，便能安顿人心。天道与人性本是一源两面。' },
        { title: '三机', chapter: '上篇', source: '《阴符经》', text: '天发杀机，移星易宿；地发杀机，龙蛇起陆；人发杀机，天地反复。', explain: '当天、地、人三者之“机”发动，都会引动巨变的连锁：星宿移位、龙蛇出陆、天地翻覆。机，是潜藏而不可抗的势能，识机者能转祸为福。' },
        { title: '三盗', chapter: '中篇', source: '《阴符经》', text: '天地，万物之盗；万物，人之盗；人，万物之盗。三盗既宜，三才既安。', explain: '天地盗取万物之精华，万物盗取人之资用，人又盗取万物之利。三者相盗若恰到好处，天、地、人便各得安顿。盗非恶，失衡才是病。' },
        { title: '食其时', chapter: '中篇', source: '《阴符经》', text: '食其时，百骸理；动其机，万化安。', explain: '按时令而食，百骸自顺；把握时机而动，万变自安。养生与处世，无非“得其时、当其机”六字。' },
        { title: '绝利一源', chapter: '下篇', source: '《阴符经》', text: '绝利一源，用师十倍；三反昼夜，用师万倍。', explain: '断绝一处贪利、收摄一处心神，效力胜过十倍之师；若昼夜反复修习、纯一不杂，则胜过万倍。专注，是世间最被低估的力量。' },
        { title: '瞽聋之智', chapter: '下篇', source: '《阴符经》', text: '瞽者善听，聋者善视。绝利一源，则他窍自明。', explain: '盲人听觉敏锐，聋者目光锐利——闭塞一窍，其余反而清明。人若少分心于外欲，内在觉察便自然开显。' },
        { title: '生杀相根', chapter: '中篇', source: '《阴符经》', text: '生者死之根，死者生之根。恩生于害，害生于恩。', explain: '生与死互为根本，恩与害彼此滋生。祸福相依、利害相转，这本是道的常则。看清这一点，便不致执迷于一端。' },
        { title: '日月有数', chapter: '上篇', source: '《阴符经》', text: '日月有数，大小有定；圣功生焉，神明出焉。', explain: '日月运行自有度数，大小变化皆有定则。循此定则而行，圣功自然生起，神明自然显现。规律之中，藏着成就的密码。' }
      ],
      yizhou: [
        { title: '天行健', chapter: '乾卦·象传', source: '《周易》', text: '天行健，君子以自强不息。', explain: '天的运行刚健有力，君子效法它，自我图强永不停息。这不是外在的拼搏，而是内在生命力的自然流露——如日月运行，不求而自成。' },
        { title: '地势坤', chapter: '坤卦·象传', source: '《周易》', text: '地势坤，君子以厚德载物。', explain: '大地的气势柔顺厚重，君子效法它，以深厚的德行承载万物。刚柔相济才是完整的修养：有自强之志，亦有包容之量。' },
        { title: '一阴一阳', chapter: '系辞上传', source: '《周易》', text: '一阴一阳之谓道。继之者善也，成之者性也。', explain: '阴阳的交互运化就是“道”。能够承继道的是善，能够成就道的是性。这句话点出了宇宙的根本法则——二元对立统一，生生不息。' },
        { title: '穷则变', chapter: '系辞下传', source: '《周易》', text: '穷则变，变则通，通则久。', explain: '路走不通了就要变革，变革了才能通达，通达了才能长久。人生困顿时不必焦虑，因为困境本身就是转机的起点。易学的精髓在于“变”中求通。' },
        { title: '潜龙勿用', chapter: '乾卦·初九', source: '《周易》', text: '潜龙勿用。阳在下也。', explain: '龙潜伏在水下，不宜妄动。时运未到、根基未稳时，最宜蓄势潜藏。强出头反招损，懂得蛰伏才是真智慧。' },
        { title: '亢龙有悔', chapter: '乾卦·上九', source: '《周易》', text: '亢龙有悔。盈不可久也。', explain: '龙飞到极高之处，便要后悔——满盈之势难以持久。盛时当知退，居高位而不骄，方能免于物极必反。' },
        { title: '履霜坚冰', chapter: '坤卦·初六', source: '《周易》', text: '履霜，坚冰至。', explain: '踩到秋霜，便知坚冰将至。见微知著、防祸于未然，是《易》教给我们最朴素的警觉。' },
        { title: '积善余庆', chapter: '坤卦·文言', source: '《周易》', text: '积善之家，必有余庆；积不善之家，必有余殃。', explain: '善行积累，福泽惠及子孙；恶行积累，灾殃牵连家人。因果不在一朝一夕，而在日积月累。' },
        { title: '二人同心', chapter: '系辞上传', source: '《周易》', text: '二人同心，其利断金；同心之言，其臭如兰。', explain: '两人心意相通，力量可断金石；同心的话语，气息如兰般芬芳。信任与默契，是人间最坚固的纽带。' },
        { title: '藏器于身', chapter: '系辞下传', source: '《周易》', text: '君子藏器于身，待时而动。', explain: '君子平日常将才器具藏于身，等待时机成熟才出手。不张扬、不急躁，蓄力于静，发劲于时。' },
        { title: '谦谦君子', chapter: '谦卦·初六', source: '《周易》', text: '谦谦君子，卑以自牧也。', explain: '谦逊的君子，以谦卑来修养、约束自己。谦不是软弱，而是一种含容万物、不居功自傲的厚德。' },
        { title: '见善则迁', chapter: '益卦·象传', source: '《周易》', text: '见善则迁，有过则改。', explain: '见到善行便向往追随，发现自己有过错便立即改正。这八个字，是日用常行的修身功课，至简至切。' },
        { title: '善不积', chapter: '系辞下传', source: '《周易》', text: '善不积不足以成名，恶不积不足以灭身。', explain: '善行不积累，不足以成就美名；恶行不积累，也不足以毁掉自身。勿以善小而不为，勿以恶小而为之。' },
        { title: '穷理尽性', chapter: '说卦传', source: '《周易》', text: '穷理尽性，以至于命。', explain: '穷尽事理、洞明本性，方能通达天命。由格物以至于知命，是儒家与易学共许的修行次第。' }
      ],
      zhuangzi: [
        { title: '逍遥游', chapter: '逍遥游', source: '《庄子》', text: '北冥有鱼，其名为鲲。鲲之大，不知其几千里也。', explain: '庄子开篇即以鲲鹏之喻，打破我们对“大小”“长短”的固有执念。真正的自由不是身体的无拘无束，而是心灵不被成见和欲望所束缚。' },
        { title: '庄周梦蝶', chapter: '齐物论', source: '《庄子》', text: '昔者庄周梦为蝴蝶，栩栩然蝴蝶也……不知周之梦为蝴蝶与？', explain: '庄子通过梦蝶提出终极追问：究竟什么是真实的？人生如梦，梦如人生，与其纠结真假，不如放下分别心，体验当下的自在。' },
        { title: '无用之用', chapter: '人间世', source: '《庄子》', text: '人皆知有用之用，而莫知无用之用也。', explain: '人人都知道“有用”的好处，却不知道“无用”的大用。歪脖子树因“不成材”而得以终其天年——有时候，不争不抢、看似无用，恰恰是最大的保全与智慧。' },
        { title: '相濡以沫', chapter: '大宗师', source: '《庄子》', text: '相濡以沫，不如相忘于江湖。', explain: '泉水干涸时鱼儿以唾沫相互润湿，这固然感人，但不如各自在江湖中畅游、彼此遗忘。庄子告诉我们：最高境界的慈悲是不需要互相拖累的各自安好。' },
        { title: '吾生有涯', chapter: '养生主', source: '《庄子》', text: '吾生也有涯，而知也无涯。以有涯随无涯，殆已。', explain: '生命有限，知识无限，以有限追逐无限，只会疲敝。庄子不是教人弃学，而是提醒：懂得取舍、适可而止，才是养生的真意。' },
        { title: '庖丁解牛', chapter: '养生主', source: '《庄子》', text: '庖丁为文惠君解牛……依乎天理，批大郤，导大窾。', explain: '庖丁十九年刀刃如新，因他顺其纹理、避其骨节。处世亦如此：不硬碰硬，顺着事物的自然缝隙而行，便能游刃有余。' },
        { title: '井蛙夏虫', chapter: '秋水', source: '《庄子》', text: '井蛙不可以语于海者，拘于虚也；夏虫不可以语于冰者，笃于时也。', explain: '困在井底的蛙，无法谈大海；活不过夏天的虫，无法谈冰雪。人的见识受限于处境，谦逊地承认局限，才能向更广阔的世界敞开。' },
        { title: '鹪鹩偃鼠', chapter: '逍遥游', source: '《庄子》', text: '鹪鹩巢于深林，不过一枝；偃鼠饮河，不过满腹。', explain: '小鸟在密林中只需一根枝丫筑巢，鼹鼠饮河水不过填饱一肚。人所需其实很少，贪多反成负累，知足便得逍遥。' },
        { title: '朝菌蟪蛄', chapter: '逍遥游', source: '《庄子》', text: '朝菌不知晦朔，蟪蛄不知春秋。', explain: '朝生暮死的菌不知月有朔望，夏生秋死的蝉不知有春秋。生命长短不同，所见时空便不同。放下“以己度人”的傲慢，方见天地之阔。' },
        { title: '抟扶摇', chapter: '逍遥游', source: '《庄子》', text: '鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里。', explain: '大鹏南飞，击水三千、乘风九万里。宏伟的志向需要厚积的风力与广阔的视野——小知不及大知，格局决定境界。' },
        { title: '子非鱼', chapter: '秋水', source: '《庄子》', text: '子非鱼，安知鱼之乐？子非我，安知我不知鱼之乐？', explain: '庄子与惠施濠梁之辩，揭示认知的相对性：你不是我，怎知我不懂鱼的快乐？放下“唯我正确”的执念，便多一分对他人的体谅。' },
        { title: '螳臂当车', chapter: '人间世', source: '《庄子》', text: '汝不知夫螳螂乎？怒其臂以当车辙，不知其不胜任也。', explain: '螳螂奋臂挡车，不自量力。庄子以此警示：认清自身分量、不逞匹夫之勇，才是保全之道。刚猛未必是勇，知止方为智。' },
        { title: '得鱼忘筌', chapter: '外物', source: '《庄子》', text: '筌者所以在鱼，得鱼而忘筌；言者所以在意，得意而忘言。', explain: '捕鱼的工具（筌）是为了鱼，捕到便可忘筌；言语是为了达意，会意便可忘言。莫把手段当目的，执着形式而忘了本心。' }
      ],
      taiyi: [
        { title: '回光守中', chapter: '第一章', source: '《太乙金华宗旨》', text: '回光者，返照也。返照者，返其本有之性也。', explain: '“回光”就是将向外追逐的心光收回，照见自性本有的光明。这部丹经的核心功夫极其简洁：不需要复杂的仪式，只需将意识从外境收回，安住于当下。' },
        { title: '两眼交光', chapter: '第二章', source: '《太乙金华宗旨》', text: '两目之光，乃元神真意之体。双目谛观鼻端，自得神凝气聚。', explain: '将双眼的目光轻轻凝聚于鼻端（或眉心），是金华功法的入门关键。目光内敛则神不外散，神凝则气自然聚集，久之心光透发，如金华灿烂。' },
        { title: '守中勿忘', chapter: '第三章', source: '《太乙金华宗旨》', text: '守此一点，勿忘勿助，久之自有光明发现。', explain: '守住这一点灵光，既不忘记它（昏沉），也不刻意去助长它（急躁）。这种“不即不离”的状态正是道家修炼的中道——任其自然生长，不拔苗助长。' },
        { title: '金华乍现', chapter: '第四章', source: '《太乙金华宗旨》', text: '金华只是这一念，普现无边。才涉有为，便落边际。', explain: '“金华”就是当下一念的清净觉知，它本来遍满一切处。一旦你刻意去追求、去造作，反而落入局限。真正的修行不在作为，而在歇下一切造作后的本然显现。' },
        { title: '天心', chapter: '天心章', source: '《太乙金华宗旨》', text: '天心者，即元神也，居方寸之中，为万化之枢纽。', explain: '“天心”就是元神，安住于方寸（眉间一寸）之地，是万有变化的中枢。回光的落点，正是归向这天心。' },
        { title: '元神识神', chapter: '元神识神论', source: '《太乙金华宗旨》', text: '元神居方寸，识神居后天。回光即收识神而归元神。', explain: '人人皆有元神（先天真性）与识神（后天妄念）。修炼无非是把纷飞的识神收摄，回归清净的元神——如浪息而海现。' },
        { title: '金华即丹', chapter: '金华论', source: '《太乙金华宗旨》', text: '金华即金丹，非外物也，即一念之觉照。', explain: '世人向外求金丹，却不知金华就是当下那一念的觉照。丹不在身外、不在炉鼎，而在回光返照的清净心中。' },
        { title: '坎离交', chapter: '坎离交媾', source: '《太乙金华宗旨》', text: '坎离交媾，水火既济，则真阳自生。', explain: '坎（水）离（火）相交、心肾相济，如锅中水火调和，真阳之气自然萌生。这是内炼中“水火既济”的生动写照。' },
        { title: '炼化次第', chapter: '炼化论', source: '《太乙金华宗旨》', text: '炼精化气，炼气化神，炼神还虚，虚无所止。', explain: '修炼有次第：先化浊精为清气，再化气为神，最终神归于虚寂——虚到无可执处，便是与道合真。' },
        { title: '动静双修', chapter: '性命双修', source: '《太乙金华宗旨》', text: '动处炼性，静处炼命；性命双修，方契大道。', explain: '遇事对境时炼“性”（心之定力），静坐时炼“命”（身之精气）。性与命如鸟之双翼，偏一则跛，双修乃全。' },
        { title: '回光调息', chapter: '回光调息', source: '《太乙金华宗旨》', text: '回光与调息相须，息调则光自凝。', explain: '回光与调息相辅相成：呼吸调顺，心光自然凝聚；心光凝聚，呼吸也归于细缓。二者如车两轮，并行不悖。' },
        { title: '百日专功', chapter: '功夫次第', source: '《太乙金华宗旨》', text: '学者能百日专功，金华自然透发，如春回大地。', explain: '功夫贵在专一与恒久。若能连续百日不辍地回光，金华之光便会自然透发，如同大地回春、生机自现。' }
      ]

    };
    let currentJing = 'daodejing';
    function renderXiushenDaily(ds) {
      const d = new Date(ds.replace(/-/g, '/'));
      const start = new Date(d.getFullYear(), 0, 0);
      const idx = Math.floor((d - start) / 86400000);
      renderJingwen(currentJing, idx);
    }

    // ============ 每日养护打卡（独立数据 · 即勾即存）============
